{"command": "python3 - <<'EOF'
from taskdag.scheduler import Scheduler

def show(s):
    print(s.tasks(), "->", s.waves())

# empty graph
s = Scheduler()
assert s.waves() == []

# single task
s.add_task("a"); assert s.waves() == [["a"]]

# linear chain b->a, c->b
s = Scheduler()
for t, d in [("b","a"), ("c","b")]: s.add_dependency(t, d)
assert s.waves() == [["a"], ["b"], ["c"]], s.waves()

# diamond: b,c depend on a; d depends on b,c
s = Scheduler()
for t in "abcd": s.add_task(t)
for t, d in [("b","a"), ("c","a"), ("d","b"), ("d","c")]: s.add_dependency(t, d)
assert s.waves() == [["a"], ["b", "c"], ["d"]], s.waves()

# unbalanced levels: e depends on d; f depends on a directly (level 1)
s = Scheduler()
for t in "abcdef": s.add_task(t)
for t, d in [("b","a"), ("c","a"), ("d","b"), ("d","c"), ("e","d"), ("f","a")]:
    s.add_dependency(t, d)
w = s.waves()
assert w == [["a"], ["b", "c", "f"], ["d"], ["e"]], w

# cross-level deps: g depends on c (level 1) and f (level 1) -> level 2;
# h depends on e (level 3) -> level 4  (deps must be in strictly earlier levels)
s = Scheduler()
for t in "abcdefgh": s.add_task(t)
for t, d in [("b","a"), ("c","a"), ("d","b"), ("d","c"), ("e","d"),
             ("f","a"), ("g","c"), ("g","f"), ("h","e")]:
    s.add_dependency(t, d)
w = s.waves()
assert w == [["a"], ["b", "c", "f"], ["d", "g"], ["e"], ["h"]], w

# every task appears exactly once across waves (invariant sweep)
s = Scheduler()
import random
random.seed(7)
names = ["n%02d" % i for i in range(12)]
for n in names: s.add_task(n)
for i in range(1, 12):
    for j in range(i):  # only earlier indices -> acyclic
        if random.random() < 0.25:
            try:
                s.add_dependency(names[i], names[j])
            except ValueError:
                pass  # would-be cycle: keep acyclic guarantee
w = s.waves()
flat = [t for lv in w for t in lv]
assert sorted(flat) == s.tasks() and len(flat) == len(set(flat))
# each level sorted, deps strictly earlier than their level
pos = {t: k for k, lv in enumerate(w) for t in lv}
for name, deps in s._deps.items():
    for d in deps:
        assert pos[d] < pos[name], (d, name, pos)
for lv in w:
    assert lv == sorted(lv)
assert w[0] == [t for t in s.tasks() if not s._deps[t]]

# cycle injected by direct mutation -> ValueError, graph unchanged by call
s = Scheduler()
for t, d in [("b","a"), ("c","b")]: s.add_dependency(t, d)
s._deps["a"].add("c")
try:
    s.waves(); assert False
except ValueError as e:
    assert "cycle" in str(e)
# dependency on an unregistered name via direct mutation -> ValueError too
s = Scheduler()
s.add_dependency("b", "a")
s._deps["a"].add("ghost")
try:
    s.waves(); assert False
except ValueError:
    pass
assert s.waves.__doc__

# waves' concatenation is a valid topological order and equals topo_order set
s = Scheduler()
for t, d in [("b","a"), ("c","a"), ("d","b"), ("d","c"), ("e","d")]:
    s.add_dependency(t, d)
assert [t for lv in s.waves() for t in lv] == s.topo_order()

print("all ad-hoc waves checks passed")
