    # ----- readiness --------------------------------------------------------", "new_string": "    def dependencies(self, name):
        """Sorted list of ``name``'s DIRECT dependencies."""
        return sorted(self._deps[name])

    # ----- serialization ------------------------------------------------------
    def to_dict(self):
        """Serialize the whole graph to a plain dict.

        Returns ``{'tasks': [...], 'deps': {...}}``: ``tasks`` is the
        sorted list of ALL registered task names, and ``deps`` maps EVERY
        registered task name to the sorted list of that task's DIRECT
        dependency names (only registered tasks can appear as deps, since
        ``add_dependency`` auto-registers both endpoints). Everything is
        sorted and only builtin types are used, so the result is
        deterministic and JSON-serializable. Empty graph -> ``{'tasks':
        [], 'deps': {}}``.
        """
        return {
            "tasks": self.tasks(),
            "deps": {
                name: sorted(deps)
                for name, deps in sorted(self._deps.items())
            },
        }

    @classmethod
    def from_dict(cls, d):
        """Rebuild a Scheduler equivalent to the one that produced ``d``.

        ``d`` must have the shape returned by ``to_dict()``:
        ``{'tasks': [names...], 'deps': {name: [direct dependency
        names...]}}``. The graph is rebuilt through the public API
        (``add_task`` then ``add_dependency`` per edge), so the usual
        invariants are re-checked rather than trusted: a ``d`` that would
        create a cycle (or a self-dependency) raises ValueError instead of
        yielding an inconsistent scheduler. For any dict with that shape,
        ``from_dict(d).to_dict() == d`` -- in particular the round trip
        ``from_dict(to_dict(s)).to_dict() == s.to_dict()`` always holds.
        """
        s = cls()
        for name in d["tasks"]:
            s.add_task(name)
        for task, deps in d["deps"].items():
            for dep in deps:
                s.add_dependency(task, dep)
        return s

    # ----- readiness --------------------------------------------------------"}
